<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mini Loja do PHCC</title><link rel="stylesheet" href="estilo.css"></head><body>
<header><a href="index.html">PHCC | Mini Loja</a><nav><a href="cadastro.php">Vitrine</a> <a href="funcionario.php">Área do funcionário</a></nav></header><main>
<h1><?= $logado ? 'Gerenciamento de produtos' : 'Vitrine de produtos' ?></h1>
<?php if($erro): ?><p class="erro"><?=h($erro)?></p><?php endif; ?>
<?php if($logado): ?><section class="painel"><h2><?= $edicao?'Editar produto':'Cadastrar produto' ?></h2><p>Olá, <?=h($logado)?>!</p>
<form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(token())?>"><input type="hidden" name="acao" value="salvar"><input type="hidden" name="id" value="<?=h($edicao['id']??0)?>"><label>Nome<input name="nome" required value="<?=h($edicao['nome']??'')?>"></label><label>Preço (R$)<input type="number" name="preco" min="0.01" step="0.01" required value="<?=h($edicao['preco']??'')?>"></label><label>Foto (opcional, até 2 MB)<input type="file" name="imagem" accept="image/jpeg,image/png,image/webp"></label><button>Salvar produto</button> <?php if($edicao): ?><a href="cadastro.php">Cancelar</a><?php endif; ?></form></section><?php endif; ?>
<div class="grade"><?php foreach($produtos as $p): ?><article><?php if($p['imagem']): ?><img src="uploads/<?=h($p['imagem'])?>" alt="<?=h($p['nome'])?>"><?php else: ?><div class="foto">Sem foto</div><?php endif; ?><h2><?=h($p['nome'])?></h2><strong>R$ <?=number_format($p['preco'],2,',','.')?></strong><?php if($logado): ?><div class="acoes"><a href="?editar=<?=$p['id']?>">Editar</a><form method="post" onsubmit="return confirm('Excluir este produto?')"><input type="hidden" name="csrf" value="<?=h(token())?>"><input type="hidden" name="acao" value="excluir"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="excluir">Excluir</button></form></div><?php endif; ?></article><?php endforeach; ?></div><?php if(!$produtos): ?><p>Nenhum produto cadastrado.</p><?php endif; ?></main><footer>Mini Loja do PHCC • Projeto PHP</footer></body></html>
